                    console.error(`Error with ${modelName}:`, err);
                    if (!activeModel) continue;
                    return { text: `❌ فشل الاتصال بالنموذج: ${err.message}`, model: modelName };
                }
            }
            const errorMsg = "❌ فشل الوصول للموديلات المطلوبة. يرجى التحقق من مفتاح API أو استخدام نموذج آخر.";
            return { text: errorMsg, model: "System Error" };
        }

        // تشغيل الحلقة مع السياق الحالي
        return await runToolLoop([...chatHistory, currentTurn]);
    }

