        const res = await fetch(`https://api.github.com/repos/${GITHUB_REPO}/actions/workflows/${workflow_id}/${action}`, {
            method: 'PUT',
            headers: { 'Authorization': `token ${githubToken}` }
        });

        if (res.ok) return `✅ تم ${status === 'stop' ? 'إيقاف' : 'تفعيل'} البوت (${workflow_id}) بنجاح.`;
        const errData = await res.json();
        return `❌ فشل تغيير حالة البوت [${workflow_id}]: ${errData.message || "اسم الملف غير صحيح"}.`;
    } catch (e) { return `❌ خطأ: ${e.message}`; }
}


