, allowMultiple=false, replacementContent=        async function githubAction(path, content, message) {
            const token = getCleanGithubToken();
            if (!token) return "⚠️ خطأ: مفتاح GitHub غير متوفر (Token missing). يرجى التأكد من إعداد التوكن في الإعدادات.";

            try {
                const apiBase = `https://api.github.com/repos/${GITHUB_REPO}/contents/${path}`;

                // 1. الحصول على SHA للملف إذا كان موجوداً (ضروري للتحديث)
                const getRes = await fetch(apiBase, {
                    headers: {
                        'Authorization': `token ${token}`,
                        'Accept': 'application/vnd.github+json',
                        'Cache-Control': 'no-cache'
                    }
                });

                let sha = null;
                if (getRes.ok) {
                    const getData = await getRes.json();
                    sha = getData.sha;
                }

                // 2. إعداد البيانات للإرسال
                const body = {
                    message: message || "تحديث تلقائي بواسطة العقل المدبر",
                    content: btoa(unescape(encodeURIComponent(content)))
                };
                if (sha) body.sha = sha;

                // 3. تنفيذ طلب التحديث أو الإنشاء
                const putRes = await fetch(apiBase, {
                    method: 'PUT',
                    headers: {
                        'Authorization': `token ${token}`,
                        'Accept': 'application/vnd.github+json',
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify(body)
                });

                if (putRes.ok) return `✅ تم تنفيذ الأمر بنجاح على GitHub: ${path}`;

                const errData = await putRes.json();
                return `❌ فشل GitHub (كود ${putRes.status}): ${errData.message || 'خطأ غير معروف'}`;
            } catch (e) {
                console.error("GitHub Action Error:", e);
                return `❌ خطأ شبكة (Network/CORS Error): ${e.message}. يرجى التأكد من اتصال الإنترنت وصلاحيات التوكن.`;
            }
        }

