async function githubAction(path, content, message) {
    const token = getCleanGithubToken();
    if (!token) return "⚠️ خطأ: مفتاح GitHub غير متوفر (Token missing). يرجى التأكد من إعداد التوكن في الإعدادات.";

    try {
        const apiBase = `https://api.github.com/repos/${GITHUB_REPO}/contents/${path}`;

        // 1. الحصول على SHA للملف إذا كان موجوداً (ضروري للتحديث)
        const getRes = await fetch(apiBase, {
            headers: {
                'Authorization': `token ${token}`,
                'Accept': 'application/vnd.github+json',
                'Cache-Control': 'no-cache'
            }
        });

        let sha = null;
        if (getRes.ok) {
            const getData = await getRes.json();
            sha = getData.sha;
        }

        // 2. إعداد البيانات للإرسال
        const body = {
            message: message || "تحديث تلقائي بواسطة العقل المدبر",
            content: btoa(unescape(encodeURIComponent(content)))
        };
        if (sha) body.sha = sha;

        // 3. تنفيذ طلب التحديث أو الإنشاء
        const putRes = await fetch(apiBase, {
            method: 'PUT',
            headers: {
                'Authorization': `token ${token}`,
                'Accept': 'application/vnd.github+json',
                'Content-Type': 'application/json'
            },
            body: JSON.stringify(body)
        });

        if (putRes.ok) return `✅ تم تنفيذ الأمر بنجاح على GitHub: ${path}`;

        const errData = await putRes.json();
        return `❌ فشل GitHub (كود ${putRes.status}): ${errData.message || 'خطأ غير معروف'}`;
    } catch (e) {
        console.error("GitHub Action Error:", e);
        return `❌ خطأ شبكة (Network/CORS Error): ${e.message}. يرجى التأكد من اتصال الإنترنت وصلاحيات التوكن.`;
    }
}

async function triggerGithubWorkflow(workflow_id) {
    const token = getCleanGithubToken();
    if (!token) return "⚠️ خطأ: مفتاح GitHub غير متوفر.";
    try {
        const res = await fetch(`https://api.github.com/repos/${GITHUB_REPO}/actions/workflows/${workflow_id}/dispatches`, {
            method: 'POST',
            headers: {
                'Authorization': `token ${token}`,
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({ ref: 'main' })
        });

        if (res.ok) return `✅ تم إرسال أمر تشغيل البوت بنجاح! سيتم تحديث البيانات خلال دقائق.`;
        const errData = await res.json();
        return `❌ فشل التشغيل [${workflow_id}]: ${errData.message || "الملف غير موجود"}. يرجى استخدام listGithubWorkflows للتأكد من الاسم.`;
    } catch (e) {
        return `❌ خطأ في الاتصال: ${e.message}`;
    }
}

async function updateWorkflowStatus(workflow_id, status) {
    const token = getCleanGithubToken();
    if (!token) return "⚠️ خطأ: مفتاح GitHub غير متوفر.";
    const action = status === 'stop' ? 'disable' : 'enable';
    try {
        const res = await fetch(`https://api.github.com/repos/${GITHUB_REPO}/actions/workflows/${workflow_id}/${action}`, {
            method: 'PUT',
            headers: { 'Authorization': `token ${token}` }
        });

        if (res.ok) return `✅ تم ${status === 'stop' ? 'إيقاف' : 'تفعيل'} البوت (${workflow_id}) بنجاح.`;
        const errData = await res.json();
        return `❌ فشل تغيير حالة البوت [${workflow_id}]: ${errData.message || "اسم الملف غير صحيح"}.`;
    } catch (e) { return `❌ خطأ: ${e.message}`; }
}


let chatHistory = [];
let selectedImageBase64 = null;
const CHAT_LOG_PATH = 'chat_logs.json';

async function saveChatToStorage() {
    if (!githubToken) return;
    // حفظ السياق في ملف JSON على GitHub ليكون متاحاً من أي مكان
    await githubAction(CHAT_LOG_PATH, JSON.stringify(chatHistory, null, 2), "تحديث سياق المحادثة");
    // حفظ الـ UI محلياً للسرعة فقط
    localStorage.setItem('gemini_chat_ui', document.getElementById('aiMessages').innerHTML);
    saveModelSelection();
}

function saveModelSelection() {
    const selectedModel = document.getElementById('modelSelector').value;
    localStorage.setItem('gemini_selected_model', selectedModel);
}

async function loadChatFromStorage() {
    // تحميل واجهة المحادثة من التخزين المحلي فوراً لسرعة العرض
    const savedUi = localStorage.getItem('gemini_chat_ui');
    if (savedUi) {
        const container = document.getElementById('aiMessages');
        container.innerHTML = savedUi;
        container.scrollTop = container.scrollHeight;
    }

    // استعادة الموديل المختار
    const savedModel = localStorage.getItem('gemini_selected_model');
    if (savedModel) {
        document.getElementById('modelSelector').value = savedModel;
    }

    // ضمان الحصول على المفاتيح أولاً قبل محاولة التحميل من GitHub
    await initKeys();

    if (githubToken) {
        try {
            const res = await fetch(`https://api.github.com/repos/${GITHUB_REPO}/contents/${CHAT_LOG_PATH}`, {
                headers: { 'Authorization': `token ${githubToken}`, 'Cache-Control': 'no-cache' }
            });
            if (res.ok) {
                const data = await res.json();
                chatHistory = JSON.parse(decodeURIComponent(escape(atob(data.content))));
                console.log("✅ تم تحميل سياق المحادثة من GitHub");
            }
        } catch (e) { console.error("Error loading chat context:", e); }
    }

    const container = document.getElementById('aiMessages');
    container.scrollTop = container.scrollHeight;
}

// تهيئة المفاتيح والسياق عند تحميل الصفحة
window.addEventListener('load', loadChatFromStorage);


async function clearChatHistory() {
    chatHistory = [];
    if (githubToken) {
        await githubAction(CHAT_LOG_PATH, "[]", "تصفير المحادثة");
    }
    localStorage.removeItem('gemini_chat_ui');
    const container = document.getElementById('aiMessages');
    container.innerHTML = '<div class="msg ai">تم مسح الذاكرة العالمية. أنا جاهز لبدء مهمة جديدة!</div>';
    // alert removed per user request
}

let chatSessions = JSON.parse(localStorage.getItem('gemini_sessions') || '[]');
let currentSessionId = localStorage.getItem('gemini_current_session') || Date.now().toString();

function toggleHistory() {
    const sidebar = document.getElementById('aiHistorySidebar');
    sidebar.classList.toggle('open');
    if (sidebar.classList.contains('open')) renderHistory();
}

function renderHistory() {
    const list = document.getElementById('historyList');
    list.innerHTML = chatSessions.map(s => `
        <div class="history-item" onclick="loadSession('${s.id}')">
            <span style="overflow:hidden; text-overflow:ellipsis; white-space:nowrap; max-width:160px;">${s.title}</span>
            <div class="actions">
                <span onclick="event.stopPropagation(); renameSession('${s.id}')">✏️</span>
                <span onclick="event.stopPropagation(); deleteSession('${s.id}')">🗑️</span>
            </div>
        </div>
    `).join('');
}

function createNewChat() {
    currentSessionId = Date.now().toString();
    chatHistory = [];
    document.getElementById('aiMessages').innerHTML = '<div class="msg ai">بدأت محادثة جديدة! كيف يمكنني مساعدتك؟</div>';
    const sidebar = document.getElementById('aiHistorySidebar');
    if (sidebar.classList.contains('open')) toggleHistory();
    saveChatToStorage();
}

async function deleteSession(id) {
    chatSessions = chatSessions.filter(s => s.id !== id);
    localStorage.setItem('gemini_sessions', JSON.stringify(chatSessions));
    renderHistory();
}

function renameSession(id) {
    const newName = prompt("اسم المحادثة الجديد:");
    if (newName) {
        const session = chatSessions.find(s => s.id === id);
        if (session) session.title = newName;
        localStorage.setItem('gemini_sessions', JSON.stringify(chatSessions));
        renderHistory();
    }
}

function loadSession(id) {
    const session = chatSessions.find(s => s.id === id);
    if (session) {
        currentSessionId = id;
        chatHistory = session.history;
        rebuildChatUi();
        toggleHistory();
    }
}

function updateSendButtonState() {
    const input = document.getElementById('aiInput');
    const btn = document.getElementById('aiSendBtn');
    if (input.value.trim() !== "" || selectedFileBase64) {
        btn.classList.add('active');
    } else {
        btn.classList.remove('active');
    }
}

