async function repairSystem() {
    const report = {
        github_token_present: !!githubToken,
        gemini_key_present: !!geminiApiKey,
        repo: GITHUB_REPO,
        timestamp: new Date().toISOString()
    };

    const token = getCleanGithubToken();
    if (token) {
        try {
            const res = await fetch(`https://api.github.com/repos/${GITHUB_REPO}`, {
                headers: {
                    'Authorization': `Bearer ${token}`,
                    'Accept': 'application/vnd.github+json',
                    'X-GitHub-Api-Version': '2022-11-28'
                },
                mode: 'cors'
            });
            report.github_api_status = res.ok ? "يعمل بنجاح" : `خطأ: ${res.status}`;
            if (!res.ok) {
                const err = await res.json();
                report.github_error = err.message;
            }
            if (res.status === 401) report.recommendation = "التوكن غير صالح أو منتهي الصلاحية.";
            if (res.status === 404) report.recommendation = "المستودع غير موجود أو التوكن لا يملك صلاحية الوصول إليه.";
        } catch (e) {
            report.github_api_status = `فشل الاتصال: ${e.message}`;
            report.recommendation = "تأكد من عدم وجود قيود شبكة أو CORS.";
        }
    } else {
        report.recommendation = "يرجى إدخال GitHub Token في الإعدادات.";
    }

    return `تقرير نظام الإصلاح الذاتي:\n${JSON.stringify(report, null, 2)}`;
}

