else if (name === "searchCode") {
    const token = getCleanGithubToken();
    if (!token) toolResult = "⚠️ خطأ: توكن GitHub مطلوب للبحث.";
    else {
        async function performSearch(isRetry = false) {
            try {
                const cleanQuery = encodeURIComponent(args.query);
                const res = await fetch(`https://api.github.com/search/code?q=${cleanQuery}+repo:${GITHUB_REPO}`, {
                    headers: { 
                        'Authorization': `Bearer ${getCleanGithubToken()}`, 
                        'Accept': 'application/vnd.github+json',
                        'X-GitHub-Api-Version': '2022-11-28'
                    },
                    mode: 'cors'
                });

                if (res.status === 401 && !isRetry) {
                    await repairSystem();
                    return await performSearch(true);
                }

                if (res.status === 403) return "⚠️ تم بلوغ حد البحث في GitHub مؤقتاً. يرجى الانتظار دقيقة.";

                const data = await res.json();
                if (res.ok) {
                    const files = data.items.map(f => f.path);
                    return files.length > 0 ? `تم العثور على الكلمة في الملفات التالية: ${files.join(', ')}` : "لم يتم العثور على نتائج في الكود.";
                } else return `❌ خطأ في البحث: ${data.message}`;
            } catch(e) { 
                if (!isRetry) { await repairSystem(); return await performSearch(true); }
                return `❌ فشل الاتصال بالبحث: ${e.message}`; 
            }
        }
        toolResult = await performSearch();
    }
}

