async function githubAction(path, content, message, isRetry = false) {
    const token = getCleanGithubToken();
    if (!token) return "⚠️ خطأ: مفتاح GitHub غير متوفر.";

    try {
        const apiBase = `https://api.github.com/repos/${GITHUB_REPO}/contents/${path}`;
        const headers = {
            'Authorization': `Bearer ${token}`,
            'Accept': 'application/vnd.github+json',
            'X-GitHub-Api-Version': '2022-11-28'
        };

        const getRes = await fetch(apiBase, { method: 'GET', headers: headers, mode: 'cors' });

        if (getRes.status === 401 && !isRetry) {
            console.warn("🛠️ تلقائي: كشف خطأ توكن (401)، بدء الإصلاح...");
            await repairSystem();
            return await githubAction(path, content, message, true);
        }

        let sha = null;
        if (getRes.ok) {
            const getData = await getRes.json();
            sha = getData.sha;
        }

        const body = {
            message: message || "تحديث تلقائي بواسطة العقل المدبر",
            content: btoa(unescape(encodeURIComponent(content)))
        };
        if (sha) body.sha = sha;

        const putRes = await fetch(apiBase, {
            method: 'PUT',
            headers: headers,
            mode: 'cors',
            body: JSON.stringify(body)
        });

        if (putRes.ok) return `✅ تم التحديث بنجاح: ${path}`;

        if (putRes.status === 401 && !isRetry) {
            await repairSystem();
            return await githubAction(path, content, message, true);
        }

        const errData = await putRes.json();
        return `❌ فشل GitHub (PUT): ${errData.message}`;
    } catch (e) {
        if (!isRetry) {
            await repairSystem();
            return await githubAction(path, content, message, true);
        }
        return `❌ خطأ اتصال/CORS: ${e.message}`;
    }
}

