async function getGithubFileContent(path, isRetry = false) {
    const token = getCleanGithubToken();
    if (!token) return "⚠️ خطأ: GitHub Token غير متوفر.";
    try {
        const res = await fetch(`https://api.github.com/repos/${GITHUB_REPO}/contents/${path}`, {
            headers: {
                'Authorization': `Bearer ${token}`,
                'Accept': 'application/vnd.github+json',
                'X-GitHub-Api-Version': '2022-11-28'
            },
            mode: 'cors'
        });
        if (res.status === 401 && !isRetry) {
            await repairSystem();
            return await getGithubFileContent(path, true);
        }
        if (!res.ok) {
            const err = await res.json();
            return `❌ فشل GitHub: ${err.message}`;
        }
        const data = await res.json();
        return decodeURIComponent(escape(atob(data.content)));
    } catch (e) {
        if(!isRetry) {
            await repairSystem();
            return await getGithubFileContent(path, true);
        }
        return `❌ خطأ اتصال: ${e.message}`;
    }
}

async function listGithubFiles(path = "", isRetry = false) {
    const token = getCleanGithubToken();
    if (!token) return "⚠️ خطأ: GitHub Token غير متوفر.";
    try {
        const res = await fetch(`https://api.github.com/repos/${GITHUB_REPO}/contents/${path}`, {
            headers: {
                'Authorization': `Bearer ${token}`,
                'Accept': 'application/vnd.github+json',
                'X-GitHub-Api-Version': '2022-11-28'
            },
            mode: 'cors'
        });
        if (res.status === 401 && !isRetry) {
            await repairSystem();
            return await listGithubFiles(path, true);
        }
        if (!res.ok) {
            const err = await res.json();
            return `❌ فشل GitHub: ${err.message}`;
        }
        const data = await res.json();
        if (!Array.isArray(data)) return "⚠️ هذا ملف وليس مجلداً.";
        const files = data.map(f => `${f.type === 'dir' ? '📁' : '📄'} ${f.path}`);
        return `محتويات ${path || 'الجذر'}:\n${files.join('\n')}`;
    } catch (e) {
        if(!isRetry) {
            await repairSystem();
            return await listGithubFiles(path, true);
        }
        return `❌ خطأ اتصال: ${e.message}`;
    }
}

