async function loadChatFromStorage() {
    // تحميل واجهة المحادثة من التخزين المحلي فوراً لسرعة العرض
    const savedUi = localStorage.getItem('gemini_chat_ui');
    if (savedUi) {
        const container = document.getElementById('aiMessages');
        container.innerHTML = savedUi;
        container.scrollTop = container.scrollHeight;
    }

    // استعادة الموديل المختار
    const savedModel = localStorage.getItem('gemini_selected_model');
    if (savedModel) {
        document.getElementById('modelSelector').value = savedModel;
    }

    // ضمان الحصول على المفاتيح أولاً قبل محاولة التحميل من GitHub
    await initKeys();

    const token = getCleanGithubToken();
    if (token) {
        try {
            const res = await fetch(`https://api.github.com/repos/${GITHUB_REPO}/contents/${CHAT_LOG_PATH}`, {
                headers: {
                    'Authorization': `Bearer ${token}`,
                    'Accept': 'application/vnd.github+json',
                    'X-GitHub-Api-Version': '2022-11-28',
                    'Cache-Control': 'no-cache'
                },
                mode: 'cors'
            });
            if (res.ok) {
                const data = await res.json();
                chatHistory = JSON.parse(decodeURIComponent(escape(atob(data.content))));
                console.log("✅ تم تحميل سياق المحادثة من GitHub");
                // إعادة بناء الواجهة لضمان استمرارية الذاكرة وعدم فقدان السياق
                if (chatHistory.length > 0) rebuildChatUi();
            }
        } catch (e) { console.error("Error loading chat context:", e); }
    }

    const container = document.getElementById('aiMessages');
    container.scrollTop = container.scrollHeight;
}

