                    { name: "searchCode", description: "البحث عن كلمة أو كود في كامل المستودع دون استهلاك التوكنات. يعيد أسماء الملفات التي تحتوي على الكلمة.", parameters: { type: "OBJECT", properties: { query: { type: "STRING" } }, required: ["query"] } },
