                                try {
                                    const cleanQuery = encodeURIComponent(args.query);
                                    const res = await safeGithubFetch(`https://api.github.com/search/code?q=${cleanQuery}+repo:${GITHUB_REPO}`);

                                    if (res.status === 403) toolResult = "⚠️ تم بلوغ حد البحث في GitHub مؤقتاً. يرجى الانتظار دقيقة.";
                                    else {
                                        const data = await res.json();
                                        if (res.ok) {
                                            const files = data.items.map(f => f.path);
                                            toolResult = files.length > 0 ? `تم العثور على الكلمة في الملفات التالية: ${files.join(', ')}` : "لم يتم العثور على نتائج في الكود.";
                                        } else toolResult = `❌ خطأ في البحث: ${data.message}`;
                                    }
                                } catch(e) { toolResult = `❌ فشل الاتصال بالبحث: ${e.message}`; }
                            }
                            else if (name === "analyzeProjectStructure") {
                                try {
                                    const report = { issues: [], health: "scanning" };
                                    const filesToCheck = ['vsa.json', 'data.json', 'crypto_alerts.json'];

                                    for (const f of filesToCheck) {
                                        const content = await getGithubFileContent(f);
                                        try { JSON.parse(content); }
                                        catch(e) { report.issues.push(`خطأ في تنسيق JSON للملف: ${f}`); }
                                    }

                                    const resFiles = await safeGithubFetch(`contents/`);
                                    const rootFiles = await resFiles.json();
                                    if (!rootFiles.find(f => f.path === 'index.html')) report.issues.push("⚠️ ملف index.html غير موجود في الجذر!");

                                    toolResult = report.issues.length > 0 ? `تقرير التحليل:\n${report.issues.join('\n')}` : "✅ لا توجد مشاكل هيكلية؛ المستودع سليم ومنظم.";
                                } catch(e) { toolResult = `❌ فشل محرك التحليل: ${e.message}`; }
                            }
                            else if (name === "selfExpand") {
                                try {
                                    const indexContent = await getGithubFileContent('index.html');

                                    // 1. حقن تعريف الأداة في مصفوفة الأدوات
                                    const toolInsertionPoint = indexContent.indexOf('] }; // end_tools');
                                    let updatedContent = indexContent;

                                    // إذا لم يجد علامة النهاية، سنستخدم منطقاً ذكياً للدمج
                                    if (toolInsertionPoint !== -1) {
                                        updatedContent = indexContent.slice(0, toolInsertionPoint) + `, ${args.declaration}` + indexContent.slice(toolInsertionPoint);
                                    }

                                    // 2. حقن منطق التنفيذ في حلقة runToolLoop
                                    const logicInsertionPoint = updatedContent.indexOf('else if (name === "triggerGithubWorkflow")');
                                    if (logicInsertionPoint !== -1) {
                                        const newLogic = `else if (name === "${args.tool_name}") { ${args.implementation} }\n                            `;
                                        updatedContent = updatedContent.slice(0, logicInsertionPoint) + newLogic + updatedContent.slice(logicInsertionPoint);
                                    }

                                    toolResult = await githubAction('index.html', updatedContent, `ترقية العقل المدبر: إضافة أداة ${args.tool_name}`);
                                } catch(e) { toolResult = `❌ فشل عملية التوسع الذاتي: ${e.message}`; }
                            }
                            else if (name === "triggerGithubWorkflow") toolResult = await triggerGithubWorkflow(args.workflow_id);
                            else if (name === "updateWorkflowStatus") toolResult = await updateWorkflowStatus(args.workflow_id, args.status);
                            else if (name === "listGithubWorkflows") toolResult = await listGithubWorkflows();
                            else if (name === "listGithubFiles") toolResult = await listGithubFiles(args.path || "");
                            else if (name === "getLiveSiteData") toolResult = JSON.stringify(allData);
                            else if (name === "repairSystem") toolResult = await repairSystem();
                            else if (name === "getSiteContext") toolResult = "سياق الموقع: أكاديمية VSA متخصصة في التداول والتحليل الفني والزمني.";
                            else if (name === "injectGlobalStyles") {
                                const style = document.createElement('style');
                                style.textContent = args.css_code;
                                document.head.appendChild(style);
                                toolResult = "✅ تم تطبيق التنسيق الجديد بنجاح.";
                            }

                            history.push({ role: "model", parts: [part] });
                            history.push({ role: "user", parts: [{ functionResponse: { name: name, response: { content: toolResult } } }] });

                            // العودة للموديل بالنتيجة (مع إمكانية التبديل إذا فشل الموديل الحالي في الخطوة القادمة)
                            return await runToolLoop(history, modelName, retryModels);
                        }

                        const finalTurn = { role: "model", parts: [part], model: modelName };
                        chatHistory = history.concat([finalTurn]);
                        if (chatHistory.length > 50) chatHistory = chatHistory.slice(-50);
                        saveChatToStorage();
                        return { text: part.text, model: modelName };
                    } catch (err) {
                        console.error(`Error with ${modelName}:`, err);
                        retryModels.push(modelName);
                        continue;
                    }
                }
                return { text: "❌ فشلت جميع المحاولات مع كافة النماذج المتاحة. يرجى المحاولة لاحقاً.", model: "System Error" };
            }

            // تشغيل الحلقة مع السياق الحالي
            return await runToolLoop([...chatHistory, currentTurn]);
        }

