                return res;
            } catch (e) {
                if (!isRetry) {
                    console.warn("🛠️ محرك الأمان: خطأ شبكة، محاولة الإصلاح...");
                    await repairSystem();
                    return await safeGithubFetch(endpoint, options, true);
                }
                throw e;
            }
        }

        async function githubAction(path, content, message) {
            try {
                const apiPath = `contents/${path}`;

                // 1. الحصول على SHA
                const getRes = await safeGithubFetch(apiPath);
                let sha = null;
                if (getRes.ok) {
                    const getData = await getRes.json();
                    sha = getData.sha;
                }

                // 2. التنفيذ
                const body = {
                    message: message || "تحديث تلقائي بواسطة العقل المدبر",
                    content: btoa(unescape(encodeURIComponent(content)))
                };
                if (sha) body.sha = sha;

                const putRes = await safeGithubFetch(apiPath, {
                    method: 'PUT',
                    body: JSON.stringify(body)
                });

                if (putRes.ok) return `✅ تم التحديث بنجاح: ${path}`;
                const errData = await putRes.json();
                return `❌ فشل GitHub: ${errData.message}`;
            } catch (e) {
                return `❌ خطأ في تنفيذ المهمة: ${e.message}`;
            }
        }

