async function repairSystem() {
    const report = {
        actions_taken: [],
        status: "initiating_self_heal",
        timestamp: new Date().toISOString()
    };

    // 1. التطهير التلقائي للتوكنات (الإصلاح الذي يطلبه المستخدم)
    if (githubToken) {
        const rawToken = githubToken;
        const cleanToken = rawToken.trim().replace(/^['"]|['"]$/g, '');
        if (rawToken !== cleanToken) {
            githubToken = cleanToken;
            report.actions_taken.push("✅ تم اكتشاف توكن ملوث بعلامات تنصيص/مسافات وتم تطهيره تلقائياً.");
            // تحديث في Supabase لضمان الديمومة إذا أمكن
            try { await saveApiKeyToSupabase('github_token', cleanToken); } catch(e){}
        }
    }

    // 2. فحص سلامة سجل الدردشة (منع تعليق المتصفح)
    if (chatHistory && chatHistory.length > 50) {
        chatHistory = chatHistory.slice(-20);
        report.actions_taken.push("⚠️ سجل الدردشة كان طويلاً جداً؛ تم تقليم السجل للحفاظ على سرعة الاستجابة.");
    }

    // 3. اختبار الاتصال الفعلي وتصحيح البروتوكول
    const token = getCleanGithubToken();
    if (token) {
        try {
            const testRes = await fetch(`https://api.github.com/repos/${GITHUB_REPO}`, {
                headers: {
                    'Authorization': `Bearer ${token}`,
                    'Accept': 'application/vnd.github+json',
                    'X-GitHub-Api-Version': '2022-11-28'
                },
                mode: 'cors'
            });

            if (testRes.status === 401) {
                report.status = "critical_error";
                report.error = "التوكن غير صالح (401).";
                report.recommendation = "يرجى مسح التوكن وإعادة إدخاله بشكل صحيح.";
            } else if (testRes.ok) {
                report.status = "healthy";
                report.message = "تمت استعادة الاتصال بـ GitHub بنجاح.";
            }
        } catch (e) {
            report.status = "network_issue";
            report.error = e.message;
            // محاولة فرض بروتوكول Bearer إذا لم يكن موجوداً
            report.actions_taken.push("🔄 محاولة إعادة تهيئة رؤوس الاستعلام (Headers) لضمان التوافق.");
        }
    }

    // 4. إعادة مزامنة المفاتيح من Supabase
    try {
        await initKeys();
        report.actions_taken.push("🔄 تم تحديث المفاتيح من قاعدة البيانات المركزية.");
    } catch(e){}

    const finalMsg = `🛡️ نظام الإصلاح الذاتي (Mastermind Healer):\n\n${report.actions_taken.join('\n')}\n\nالحالة النهائية: ${report.status}\nالتوصية: ${report.recommendation || "لا يوجد تدخل يدوي مطلوب."}`;
    console.log(report);
    return finalMsg;
}

